{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at Udbetaling Danmark indhenter arbejdstimer og indkomst fra Skattestyrelsen. Det nævner heller ikke, at ansøgerens egne oplysninger om tidligere arbejdsforhold inddrages, eller at arbejde før ansøgningen kan indgå. Det har desuden væsentlige udsagn uden støtte i de aktuelle kilder, fx at studierelevans og geografi ikke tillægges vægt, og at det reducerede fribeløb er et moment. Det afviser kildernes myndighed ('ikke direkte om Udbetaling Danmark'). Samlet afviger svaret væsentligt fra rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Tre af fire kritiske elementer mangler: Skattestyrelsen som kilde til arbejdstimer og indkomst, ansøgerens egne oplysninger om tidligere arbejdsforhold, og arbejde før ansøgningen (navnlig ved ophør af andre årsager uden forværring). Kun arbejde under studiet er delvist dækket."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret beskriver hovedsagelig, hvad ankenævnsafgørelser har lagt vægt på, fx indkomstbeløb, fribeløb og skånehensyn. Det besvarer ikke, hvilke oplysninger Udbetaling Danmark indhenter og bruger, og hvorfra. Meget af indholdet, fx 'hvad indgår ikke', er ikke relevant for spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver identificerbare kilder: Ankenævnets afgørelser med journalnumre og KEN-numre på Retsinformation, og henviser med numre til dem i teksten."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De angivne kilder er ældre ankenævnsafgørelser fra 2013-2015, ikke den aktuelle vejledning (VEJ afsnit 3.4.1.3) eller SU-bekendtgørelsen i den frosne kildeafgrænsning. Svaret erkender selv, at de ikke direkte handler om Udbetaling Danmark. De er derfor ikke aktuelle og autoritative for opgaven."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De frosne passager og bestemmelser støtter ikke de centrale påstande om fribeløb, studierelevans, geografi, specialpædagogisk støtte og skånehensyn. De angivne afgørelsers indhold kan ikke verificeres i materialet, og de dækker ikke kernen, nemlig Skattestyrelsen, egne oplysninger og tidligere arbejde."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer væsentlige regler uden støtte i materialet: at fribeløbsoverskridelse peger på ikke betydeligt nedsat erhvervsevne, at studierelevans og geografi ikke tillægges vægt, at specialpædagogisk støtte og øget tidsforbrug ikke indgår, og at et studiejob 'i mindre omfang' er relevant."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Rubrikken kræver forbeholdet om, at tidligere arbejde særligt er relevant ved ophør af andre årsager uden forværring, og at oplysningerne ikke alene afgør retten. Svaret nævner intet af dette. Det fremhæver fribeløbet som et moment uden at sige, at oplysningerne indgår i en samlet vurdering."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det opstiller moment for moment, hvad afgørelserne lægger vægt på, og drager en praktisk konklusion i overensstemmelse hermed. Dets forudsætning er dog skæv i forhold til kilderne."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan' og 'typisk' flere steder, men fremstiller ikke-understøttede forhold som faste udelukkelser: 'Der lægges heller ikke vægt på...' og 'indgår ikke i vurderingen'. Det udelukker dermed forhold, som rubrikken ikke udelukker, og ændrer kildens 'navnlig'-formulering ved ikke at nævne den."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det nævner kun indkomstbeløb fra afgørelser."
    },
    "A19": {
      "label": "no",
      "reason": "Ansøgerens egne oplysninger om tidligere arbejdsforhold fra ansøgningen er ikke nævnt."
    },
    "A20": {
      "label": "partial",
      "reason": "Arbejde ved siden af studiet nævnes, så arbejde under studiet er delvist dækket. Arbejde før ansøgningen og betingelsen om ophør af andre årsager uden forværring mangler."
    }
  },
  "overall_notes": "Svaret bygger på ankenævnsafgørelser fra 2013-2015 og ikke på den aktuelle vejledning. Det udelader de centrale elementer: Skattestyrelsen, ansøgerens egne oplysninger og tidligere arbejde. Det tilføjer ikke-understøttede udsagn om fribeløb og udelukkede forhold. Kilderne er angivet (C04 opfyldt), men er ikke gyldige eller understøttende."
}

